target.css:
:root {
  --ink: #20333a;
  --muted: #688087;
  --paper: #fffdf7;
  --line: #d9e3df;
  --ice: #e9f5f4;
  --pine: #176b62;
  --lime: #b9dc55;
  --warm: #fff0c8;
}

.wax-card {
  width: 480px;
  box-sizing: border-box;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  padding: 16px 18px 14px;
  border-bottom: 1px solid var(--line);
}

.title-group {
  display: grid;
  gap: 4px;
}

.eyebrow {
  margin: 0;
  color: var(--muted);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
}

.title-group h1 {
  margin: 0;
  font-size: 23px;
  line-height: 1;
  letter-spacing: -0.5px;
}

.status {
  display: flex;
  align-items: center;
  gap: 6px;
  margin: 1px 0 0;
  padding: 6px 9px;
  border-radius: 999px;
  background: var(--ice);
  color: var(--pine);
  font-size: 12px;
  font-weight: 700;
}

.status-dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: var(--lime);
}

.ski-summary {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 13px 18px;
  background: var(--ice);
}

.ski-icon {
  display: grid;
  width: 38px;
  height: 38px;
  place-items: center;
  border-radius: 12px;
  background: var(--warm);
  font-size: 21px;
}

.ski-summary h2 {
  margin: 0 0 2px;
  font-size: 14px;
  line-height: 1.2;
}

.ski-summary p {
  margin: 0;
  color: var(--muted);
  font-size: 12px;
}

.service-list {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 0;
  margin: 0;
  padding: 12px 18px;
  list-style: none;
}

.service-list li {
  display: grid;
  gap: 5px;
  padding: 2px 12px;
  border-right: 1px solid var(--line);
}

.service-list li:first-child {
  padding-left: 0;
}

.service-list li:last-child {
  padding-right: 0;
  border-right: 0;
}

.service-list span {
  color: var(--muted);
  font-size: 11px;
}

.service-list strong {
  font-size: 12px;
}

.card-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 11px 18px;
  border-top: 1px solid var(--line);
}

.card-footer p {
  margin: 0;
  color: var(--pine);
  font-size: 12px;
  font-weight: 700;
}

.card-footer p span {
  margin-right: 6px;
  color: var(--muted);
  font-weight: 400;
}

.card-footer button {
  padding: 7px 11px;
  border: 1px solid var(--pine);
  border-radius: 8px;
  background: var(--pine);
  color: var(--paper);
  font-size: 12px;
  font-weight: 700;
}

